const priceForQty = (bean, qty) => {
  if (!bean || !qty) return null;
  if (bean.prices && bean.prices[qty] != null) return bean.prices[qty];
  if (bean.pricePerKg) return Math.round((bean.pricePerKg / 1000) * qty + 45);
  return null;
};

const qtyOptionsFor = (bean) => {
  if (bean && bean.prices) return Object.keys(bean.prices).map(Number).sort((a, b) => a - b);
  return [250, 500, 1000];
};

const dripBoxPrice = (bean) => (bean && bean.dripPricePerBox) || 160;

