const RoastCurveChart = ({ curve }) => {
  const W = 320, H = 190;
  const padL = 34, padR = 14, padT = 16, padB = 26;
  const tMax = 13, Tmin = 105, Tmax = 178;
  const x = t => padL + (t / tMax) * (W - padL - padR);
  const y = T => (H - padB) - ((T - Tmin) / (Tmax - Tmin)) * (H - padT - padB);
  const pts = curve.map(c => [x(c.t), y(c.T)]);
  const linePath = pts.map((p, i) => (i === 0 ? "M" : "L") + p[0].toFixed(1) + "," + p[1].toFixed(1)).join(" ");
  const areaPath = linePath + ` L${pts[pts.length-1][0].toFixed(1)},${H-padB} L${pts[0][0].toFixed(1)},${H-padB} Z`;
  const gridTemps = [120, 140, 160];
  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" height="auto" style={{ display:"block" }}>
      {gridTemps.map(gt => (
        <g key={gt}>
          <line x1={padL} x2={W - padR} y1={y(gt)} y2={y(gt)} stroke="rgba(131,131,131,0.18)" strokeWidth="1" strokeDasharray="3 3" />
          <text x={padL - 6} y={y(gt) + 3} textAnchor="end" fontSize="8.5" fill="#9A9090" fontFamily="sans-serif">{gt}°</text>
        </g>
      ))}
      <line x1={padL} x2={W - padR} y1={H - padB} y2={H - padB} stroke="rgba(131,131,131,0.3)" strokeWidth="1" />
      <path d={areaPath} fill="rgba(184,146,74,0.12)" stroke="none" />
      <path d={linePath} fill="none" stroke="#B5694F" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
      {curve.map((c, i) => (
        <g key={c.stage}>
          <circle cx={x(c.t)} cy={y(c.T)} r="4.5" fill="#FCF8F2" stroke="#8A4332" strokeWidth="2" />
          <text x={x(c.t)} y={y(c.T) - 10} textAnchor={i === 0 ? "start" : i === curve.length - 1 ? "end" : "middle"} fontSize="9" fontWeight="700" fill="#2E2A2A" fontFamily="sans-serif">{c.T}°</text>
          <text x={x(c.t)} y={H - padB + 14} textAnchor={i === 0 ? "start" : i === curve.length - 1 ? "end" : "middle"} fontSize="8" fill="#9A9090" fontFamily="sans-serif">{c.time}</text>
        </g>
      ))}
    </svg>
  );
};

